import{_ as s,o as n,c as t,a4 as e}from"./chunks/framework.BRzJ4ijD.js";const k=JSON.parse('{"title":"WAL、fsync、崩溃一致性","description":"","frontmatter":{},"headers":[],"relativePath":"os/fs/crash-consistency.md","filePath":"os/fs/crash-consistency.md","lastUpdated":1788475713000}'),i={name:"os/fs/crash-consistency.md"};function p(l,a,c,r,o,d){return n(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="wal、fsync、崩溃一致性" tabindex="-1">WAL、fsync、崩溃一致性 <a class="header-anchor" href="#wal、fsync、崩溃一致性" aria-label="Permalink to &quot;WAL、fsync、崩溃一致性&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>工程上 90% 的&quot;数据丢失 bug&quot; 都因为误以为 write 成功就持久了, 误以为 fsync 一定成功就持久了. 这一章把 Linux + ext4 + NVMe 下的崩溃一致性模型拆开, 让你看到<strong>write / fsync / fdatasync / 终端 cache / 设备电池</strong> 这五层覆盖在 CRIT between user app 与 NVM 实际写完之间.</p><h2 id="_1-五层缓存" tabindex="-1">1. 五层缓存 <a class="header-anchor" href="#_1-五层缓存" aria-label="Permalink to &quot;1. 五层缓存&quot;">​</a></h2><p>让我们从用户 <code>write(fd, buf, n)</code> 把字节真正落到 NVME cell 之间拉一次完整路径:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. user 写 page cache: write 调用 → mark dirty</span></span>
<span class="line"><span>2. fsync(fd) 等 page cache 实际 writeback</span></span>
<span class="line"><span>3. writeback → block layer → 组 bio → submit</span></span>
<span class="line"><span>4. NVMe driver → submission queue → 设备</span></span>
<span class="line"><span>5. NVMe controller 实际 NAND write + flush + checkpoint</span></span>
<span class="line"><span>6. NAND cell 物理 charge 写入完成 ack</span></span></code></pre></div><p><strong>每层都是一个 cache</strong>, 每层都可丢失. 这就是为什么 fsync 也不 100% 安全:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ext4 fsync → journal commit → 块层 write → NVMe cache → NAND.</span></span></code></pre></div><p>如果 NVMe 设备有 cache 而 fsync 提交需求没 pass through NVMe cache flush, <strong>fsync ack 但 cache 没到 NAND, 断电仍丢</strong>. 这是真实硬件隐患.</p><h2 id="_2-fsink-提交语义" tabindex="-1">2. fsink 提交语义 <a class="header-anchor" href="#_2-fsink-提交语义" aria-label="Permalink to &quot;2. fsink 提交语义&quot;">​</a></h2><p>ext4 / XFS / Btrfs 三种 fs 主流方式:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ext4 default data=ordered:</span></span>
<span class="line"><span>  - dirty pages 先 flushed to data area,</span></span>
<span class="line"><span>  - journal commit 中写 metadata commit block,</span></span>
<span class="line"><span>  - fsync 等 journal commit 完成才 return.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ext4 data=writeback:</span></span>
<span class="line"><span>  - 仅 metadata journal;</span></span>
<span class="line"><span>  - data 可能 metadata 之后写 → 看到 stale block.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ext4 data=journal:</span></span>
<span class="line"><span>  - 全部 data journal;</span></span>
<span class="line"><span>  - 安全但写放太严重 2× overhead.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>XFS 默认 delay-write:</span></span>
<span class="line"><span>  - 类 ordered, 但数据 first delayed write then block flush.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Btrfs:</span></span>
<span class="line"><span>  - 每 fsync 触发 transid++ commit CoW;</span></span>
<span class="line"><span>  - 同 XFS 类性能.</span></span></code></pre></div><p>主要不同: 默认 ext4 <code>data=ordered</code> 保证了 <strong>data 不会比 metadata 先丢</strong>——避免 commit metadata 后看到 stale block. 这就是早期 Linux 2.4 NFS 比 ext3 data=journal 用 5 年才改的原因: 写 + crash 后 fs state 一致.</p><h2 id="_3-fdatasync-卷语义" tabindex="-1">3. fdatasync 卷语义 <a class="header-anchor" href="#_3-fdatasync-卷语义" aria-label="Permalink to &quot;3. fdatasync 卷语义&quot;">​</a></h2><p><code>fdatasync</code> 不强制 metadata 中 atime/mtime 写盘, 但<strong>强制 data 写盘</strong>. 对 append-only log 是 fdatasync 性能更好.</p><p>原因:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fsync:</span></span>
<span class="line"><span>  ## 必等 metadata (size, mtime 等) 写盘</span></span>
<span class="line"><span>  ## 强制 journal commit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fdatasync:</span></span>
<span class="line"><span>  ## data 写盘</span></span>
<span class="line"><span>  ## 仅在 size 改变时 fs 元数据也 stdsync flush</span></span></code></pre></div><p><strong>append-only log 上</strong>: 强制 size metadata 也 flush 当且仅当最后大小必须被下次 fs 状态读取. 否则 fdatasync 安全.</p><h2 id="_4-nvme-force-unit-access-fua-与-volatile-write-cache-vwc" tabindex="-1">4. NVMe Force Unit Access (FUA) 与 Volatile Write Cache (VWC) <a class="header-anchor" href="#_4-nvme-force-unit-access-fua-与-volatile-write-cache-vwc" aria-label="Permalink to &quot;4. NVMe Force Unit Access (FUA) 与 Volatile Write Cache (VWC)&quot;">​</a></h2><p>NVMe 命令支持 bit:</p><ul><li>FUA = Force Unit Access. 命令绕 device cache 直接到 NAND;</li><li>只 NVM 终端 fdatasync 是不够的 —— 内核驱动通过 IO command <code>Flush</code> 给设备写盘.</li></ul><p><strong>SCSI 类硬盘 / 部分 NVMe</strong> 有 volatile write cache. 设备自我 ack fast 但吸收在 device buf. 断电时 buf dump. Linux <code>write cache = write through</code> 与 <code>write back</code> 区分:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hdparm -W0 /dev/sda   # 关闭 write cache</span></span></code></pre></div><p>关掉 write cache = performance drop 30-50% 但 fsync ack 即感真持久化. HRT / database 推荐.</p><h2 id="_5-崩溃一致性概念" tabindex="-1">5. 崩溃一致性概念 <a class="header-anchor" href="#_5-崩溃一致性概念" aria-label="Permalink to &quot;5. 崩溃一致性概念&quot;">​</a></h2><p><strong>durability</strong>: 一次 fsync 后数据一定持久化 ⇒ ack 后断电也能 find.</p><p><strong>atomicity</strong>: 写 multi-block 全完成或全未.</p><p><strong>isolation</strong>: 在崩溃之后看到的 fs state, 等同 某个 in-order 之前完成 fsync 的快照.</p><p>ext4 ordered 默认满足: durability (fsync 等到 commit) + atomicity (journal) + isolation (transid).</p><p>但 ext4 writeback 不满足 atomicity (data 不 journal) ⇒ fsck 后你也许看到 partial data write + commit metadata.</p><h2 id="_6-wal-write-ahead-log-数据库的核心设计" tabindex="-1">6. WAL (Write-Ahead Log) 数据库的核心设计 <a class="header-anchor" href="#_6-wal-write-ahead-log-数据库的核心设计" aria-label="Permalink to &quot;6. WAL (Write-Ahead Log) 数据库的核心设计&quot;">​</a></h2><p>数据库为了保证 ACID, <strong>什么 dirty pages 都先写 WAL redo log</strong> + fsync.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事务 commit 步骤:</span></span>
<span class="line"><span>1. 修改 buffer pool pool page (in-mem);</span></span>
<span class="line"><span>2. 写 WAL redo log append (in-mem);</span></span>
<span class="line"><span>3. fsync(WAL fd);      ← 等待 truly persistent;</span></span>
<span class="line"><span>4. ack 客户端 &quot;commit ok&quot;;</span></span>
<span class="line"><span>5. 后台异步 flush dirty page buffer pool → disk (写 data file).</span></span></code></pre></div><p>崩溃 ~ 准 back eventually: WAL fsync 后 ack 即持久, data file 后续 lazy flush 是 ok 的. crash 后, 启动读 WAL, redo 重做 final commit.</p><p>这就是 <strong>InnoDB / PostgreSQL / RocksDB / CockroachDB 共同的 WAL 模型</strong>. 核心思想: <strong>持久化只需要 redo fsync 一次, data 落盘可以 amortized</strong>.</p><h2 id="_7-数据库的-group-commit-优化" tabindex="-1">7. 数据库的 group commit 优化 <a class="header-anchor" href="#_7-数据库的-group-commit-优化" aria-label="Permalink to &quot;7. 数据库的 group commit 优化&quot;">​</a></h2><p>每 fsync ~ 100 μs - 5 ms, 不能每事务都做. → 组 commit: 多个事务的 WAL 一起进程, 一次 fsync 同时段 完成所有事务.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>所有 commit_req 入队列,</span></span>
<span class="line"><span>线程 1 持有队列, 等待时间窗口 (e.g. 100 μs) 让 batch grow,</span></span>
<span class="line"><span>后 fsync 1 次, ack 全队员.</span></span></code></pre></div><p>MySQL 5.7 提 <code>binlog_group_commit</code>, MySQL 8 后 Innodb redo log 也用 group commit, 单次 fsync 容纳 ~ 100+ 事务.</p><p><strong>P99 写延迟</strong>: 1 个 commit ~ 5 ms (fsync overhead)→ group 100 个事务: ~ 5 ms / 100 = 50 μs / commit.</p><h2 id="_8-数据库-ext4-xfs-btrfs-调优建议" tabindex="-1">8. 数据库 + ext4 / XFS / Btrfs 调优建议 <a class="header-anchor" href="#_8-数据库-ext4-xfs-btrfs-调优建议" aria-label="Permalink to &quot;8. 数据库 + ext4 / XFS / Btrfs 调优建议&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ext4 database mount options</span></span>
<span class="line"><span>mount -o noatime,nodiratime,data=writeback,barrier=1 /dev/sda1 /data</span></span>
<span class="line"><span># noatime: 不更新 atime (减少 metadata IO)</span></span>
<span class="line"><span># data=writeback: 不 journal data (WAL 已经保证 atomicity)</span></span>
<span class="line"><span># barrier=1: 关键 — 所有 metadata journal commit 必 flush device cache</span></span></code></pre></div><p><strong>barrier=1 是关键</strong>: 关闭 barrier 意味着 journalist commit 在 ext4 层完成 (in mem journal) 而设备 cache 没写. 断电破坏 fs ordering.</p><h2 id="_9-多语言-多-runtime-同一抽象" tabindex="-1">9. 多语言 / 多 runtime 同一抽象 <a class="header-anchor" href="#_9-多语言-多-runtime-同一抽象" aria-label="Permalink to &quot;9. 多语言 / 多 runtime 同一抽象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语言 / runtime</th><th>fsync / commit 模型</th></tr></thead><tbody><tr><td>C / C++ std</td><td>explicit fsync + 一次 syscall</td></tr><tr><td>Go os.File</td><td>同上</td></tr><tr><td>Rust std::fs</td><td>File::sync_all → fsync</td></tr><tr><td>Java NIO</td><td>FileChannel.force(true)</td></tr><tr><td>Python</td><td>file.flush() + os.fsync(fd)</td></tr><tr><td>SQLite</td><td>default 通过 WAL + fsync</td></tr><tr><td>PostgreSQL</td><td>fsync + group commit + WAL</td></tr><tr><td>RocksDB</td><td>别提了 + 每 wrapper fsync</td></tr><tr><td>Redis</td><td>每 BGSAVE + RDB + AOF fsync (slow mode)</td></tr></tbody></table><p>所有持久化数据库都需要 fsync at least once per logical update. fsync 是 OS / 设备间义务.</p><h2 id="_10-旋涡调试" tabindex="-1">10. 旋涡调试 <a class="header-anchor" href="#_10-旋涡调试" aria-label="Permalink to &quot;10. 旋涡调试&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 强制清 cache</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/sys/vm/drop_caches</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 看 ext4 commit interval</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/mounts</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 看 NVMe cache 状态</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nvme</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> id-ctrl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cache</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 关 write cache (warn: 性能降)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hdparm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -W0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/sda1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在 PG 里面 pgbench with synchronous_commit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pgbench</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -j</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -M</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prepared</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --protocol=prepared</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mydb</span></span></code></pre></div><h2 id="_11-这一章带走的东西" tabindex="-1">11. 这一章带走的东西 <a class="header-anchor" href="#_11-这一章带走的东西" aria-label="Permalink to &quot;11. 这一章带走的东西&quot;">​</a></h2><ul><li>write 不保证持久化, fsync 才真持久化, 但仍依赖 device cache;</li><li>ext4 data=ordered default 是历史正确选择, database 推荐 data=writeback + barrier=1;</li><li>WAL 模型让 fsync 摊还到 commit batched (group commit);</li><li>fsync P99 是数据库 commit P99 上界, group commit 拿到 100× throughput;</li><li>NVMe cache / FUA / barrier=1 是 fsync 与 device 层的合作 contact.</li></ul><p>下一节 → <a href="./../sched/">进程与线程调度</a></p>`,51)])])}const u=s(i,[["render",p]]);export{k as __pageData,u as default};
